import json,requests,subprocess,hashlib
from pathlib import Path
p=Path('/tmp/goodsentry-closure-028');f=json.loads((p/'browser-fixture.json').read_text());base='http://127.0.0.1:18530';wire=(p/'exporters/json-identity-0.wire').read_bytes();assert len(wire)>1024
q="select encode(payload,'hex') from otlp_log_batches where id=10 and project_id=4";cmd=['docker','exec','gsclosure028-postgres-1','psql','-U','closure028','-d','closure028_limit','-Atc',q];before=bytes.fromhex(subprocess.check_output(cmd,text=True).strip());assert len(before)>1024
s=requests.Session();login=s.post(base+'/api/v1/login',headers={'Origin':base},json={'email':f['ownerEmail'],'password':f['ownerPassword']},timeout=15);assert login.status_code==200;log=s.get(base+f"/api/v1/organizations/{f['orgSlug']}/logs",params={'project':f['projectId'],'query':f['expectedBody']},timeout=15);assert log.status_code==200 and len(log.json()['data'])==1;logid=log.json()['data'][0]['id'];detail=s.get(base+f"/api/v1/organizations/{f['orgSlug']}/logs/{logid}",timeout=15);assert detail.status_code==200
r=requests.post(base+'/v1/logs',headers={'Content-Type':'application/json','X-GoodSentry-Key':f['publicKey']},data=wire,timeout=15);assert r.status_code==413;again=s.get(base+f"/api/v1/organizations/{f['orgSlug']}/logs/{logid}",timeout=15);assert again.status_code==200 and again.json()==detail.json();after=bytes.fromhex(subprocess.check_output(cmd,text=True).strip());assert before==after
report={'passed':True,'limitBytes':1024,'rejectedWireBytes':len(wire),'rejectionStatus':r.status_code,'retainedBatchBytes':len(before),'retainedBatchSHA256':hashlib.sha256(before).hexdigest(),'detailUnchanged':True,'logId':logid};(p/'limit-report.json').write_text(json.dumps(report,indent=2));print(json.dumps(report))
